old="function download(url,name){let a=document.createElement('a');a.href=url;a.download=name;a.click()}$('#exportPng').onclick=()=>{let c=document.createElement('canvas');c.width=W*4;c.height=H*8;let k=c.getContext('2d');for(let i=0;i<N;i++){k.drawImage(frames[i][0],(i%4)*W,Math.floor(i/4)*H);k.drawImage(frames[i][1],(i%4)*W,Math.floor(i/4)*H)}download(c.toDataURL('image/png'),'Walk-Anim-PARTIEL.png')};"
new="function download(url,name){let a=document.createElement('a');a.href=url;a.download=name;a.click()}function mergedSheet(){let c=document.createElement('canvas');c.width=W*4;c.height=H*8;let k=c.getContext('2d');for(let i=0;i<N;i++){k.drawImage(frames[i][0],(i%4)*W,Math.floor(i/4)*H);k.drawImage(frames[i][1],(i%4)*W,Math.floor(i/4)*H)}return c.toDataURL('image/png')}$('#exportPng').onclick=()=>download(mergedSheet(),'Walk-Anim-PARTIEL.png');$('#sendMap').onclick=()=>{if(!frames.length)return;if(window.parent===window){alert('Ouvre cet éditeur depuis l’aperçu carte pour lui envoyer la planche.');return}window.parent.postMessage({type:'mega-walk-editor-sheet',png:mergedSheet()},'*');$('#status').textContent='Planche envoyée à la carte. Pense à exporter le projet JSON pour la conserver.'};"
assert old in s;s=s.replace(old,new);p.write_text(s)
p=r/'Donjon-actuel/modele.html';s=p.read_text();s=s.replace('<button id="recenter">Recentrer</button>', '<button id="recenter">Recentrer</button><button id="restoreSheet" title="Annule l’affichage de la planche envoyée par l’éditeur sur la carte">Rétablir la planche intégrée</button>')
