s=s.replace("document.querySelector('#sheetDownload').onclick=()=>", "window.addEventListener('message',e=>{if(e.source!==document.querySelector('#editorFrame').contentWindow||!e.data||e.data.type!=='mega-walk-editor-sheet'||typeof e.data.png!=='string'||!e.data.png.startsWith('data:image/png;base64,')||e.data.png.length>10000000)return;let candidate=new Image();candidate.onload=()=>{if(candidate.naturalWidth===256&&candidate.naturalHeight===896){mega.src=e.data.png;document.querySelector('#sheetStatus').textContent='Planche envoyée par l’éditeur (non sauvegardée automatiquement).'}};candidate.src=e.data.png});document.querySelector('#restoreSheet').onclick=()=>{mega.src=originalMega;document.querySelector('#sheetStatus').textContent='Planche intégrée rétablie. Les modifications dans l’éditeur restent en mémoire.'};document.querySelector('#sheetDownload').onclick=()=>")
s=s.replace('<p class="muted" id="availability"></p>', '<p class="muted" id="availability"></p><p class="muted" id="sheetStatus">Planche intégrée. Les modifications de l’éditeur peuvent être envoyées à la carte.</p>')
